/**
 * 문의에 참여합니다. 이미 참여 중이면 온라인 상태로 변경됩니다.
 * @summary 문의 참여
 */
export const joinInquiry = (
	inquiryId: string,
	joinInquiryBody: BodyType<JoinInquiryBody>,
	options?: SecondParameter<typeof customInstance>,
	signal?: AbortSignal,
) => {
	return customInstance<JoinInquiry200AllOf>(
		{
			url: `/api/v1/inquiries/${inquiryId}/participants/join`,
			method: "POST",
			headers: { "Content-Type": "application/json" },
			data: joinInquiryBody,
			signal,
		},
		options,
	);
};

export const getJoinInquiryMutationOptions = <
	TError = ErrorType<void>,
	TContext = unknown,
>(options?: {
	mutation?: UseMutationOptions<
		Awaited<ReturnType<typeof joinInquiry>>,
		TError,
		{ inquiryId: string; data: BodyType<JoinInquiryBody> },
		TContext
	>;
	request?: SecondParameter<typeof customInstance>;
}): UseMutationOptions<
	Awaited<ReturnType<typeof joinInquiry>>,
	TError,
	{ inquiryId: string; data: BodyType<JoinInquiryBody> },
	TContext
> => {
	const mutationKey = ["joinInquiry"];
	const { mutation: mutationOptions, request: requestOptions } = options
		? options.mutation &&
			"mutationKey" in options.mutation &&
			options.mutation.mutationKey
			? options
			: { ...options, mutation: { ...options.mutation, mutationKey } }
		: { mutation: { mutationKey }, request: undefined };

	const mutationFn: MutationFunction<
		Awaited<ReturnType<typeof joinInquiry>>,
		{ inquiryId: string; data: BodyType<JoinInquiryBody> }
	> = (props) => {
		const { inquiryId, data } = props ?? {};

		return joinInquiry(inquiryId, data, requestOptions);
	};

	return { mutationFn, ...mutationOptions };
};

export type JoinInquiryMutationResult = NonNullable<
	Awaited<ReturnType<typeof joinInquiry>>
>;
export type JoinInquiryMutationBody = BodyType<JoinInquiryBody>;
export type JoinInquiryMutationError = ErrorType<void>;

/**
 * @summary 문의 참여
 */
export const useJoinInquiry = <TError = ErrorType<void>, TContext = unknown>(
	options?: {
		mutation?: UseMutationOptions<
			Awaited<ReturnType<typeof joinInquiry>>,
			TError,
			{ inquiryId: string; data: BodyType<JoinInquiryBody> },
			TContext
		>;
		request?: SecondParameter<typeof customInstance>;
	},
	queryClient?: QueryClient,
): UseMutationResult<
	Awaited<ReturnType<typeof joinInquiry>>,
	TError,
	{ inquiryId: string; data: BodyType<JoinInquiryBody> },
	TContext
> => {
	const mutationOptions = getJoinInquiryMutationOptions(options);

	return useMutation(mutationOptions, queryClient);
};
